const lesson8BTNC=[{"file":"Q2B8.NC1.MP3","title":"Nâng cao 1","key":["D","E","C","B","A"],"transcript":["我第一次下厨时，连洋葱都不会切，差点切到自己的手。","我姐姐是高手，她做的生日蛋糕又好看又好吃。","每到春节，我们全家就会围在一起包饺子。","现在年轻人喜欢跟着博主的视频学做菜，既方便又有趣。","这道红烧肉我妈妈做得最好，我真喜欢这个味道。"],"questions":[["他第一次下厨时不会做什么？",["包饺子","切洋葱","做沙拉"],1],["姐姐做的什么又好看又好吃？",["生日蛋糕","红烧肉","饺子"],0],["他们全家什么时候一起包饺子？",["中秋节","周末","春节"],2],["年轻人跟着什么学做菜？",["报纸","博主的视频","广播"],1],["谁做的红烧肉最好？",["爸爸","姐姐","妈妈"],2]]},{"file":"Q2B8.NC2.MP3","title":"Nâng cao 2","key":["B","D","C","E","A"],"transcript":["女：做蛋糕时，面粉和糖的量一定要准。\n男：原来如此，怪不得我上次做的蛋糕不太好吃。","男：汤快好了，你尝尝咸淡够不够？\n女：嗯！味道正好！可以关火了。","女：炸春卷的时候油温很重要，太高或太低都不行。\n男：哦，下次我注意油温。","男：这个草莓蛋糕上的奶油花你是怎么挤的？\n女：用专门的工具，我教你。","女：要做新鲜的沙拉，最好早上去市场买刚到的蔬菜。\n男：有道理，那明天早上我们一起去吧。"],"questions":[["做蛋糕时什么的量要准？",["面粉和糖","蔬菜和肉","盐和水"],0],["她觉得汤的味道怎么样？",["太咸","正好","太淡"],1],["炸春卷时要注意什么？",["时间","颜色","油温"],2],["她用什么挤奶油花？",["筷子","专门的工具","勺子"],1],["什么时候买沙拉用的蔬菜最好？",["晚上","中午","早上"],2]]},{"file":"Q2B8.NC3.MP3","title":"Nâng cao 3","key":["B","B","C","B","C"],"transcript":["男：听说你去学做菜了？学得怎么样？\n女：刚开始学，上周学了怎么切菜。虽然有点难，但挺有意思的。","男：今晚每人要带一个自己做的菜，你准备做什么？\n女：我打算做我的好菜——可乐鸡翅，朋友们都说好吃。","男：外卖吃多了不健康，你不打算做饭吗？\n女：我试过，但我不怎么会做，做出来的味道不太好。","男：你奶奶做的泡菜真是一绝！\n女：她说，就是用新鲜的蔬菜，然后耐心地等，不能着急。","男：现在有很多教做菜的手机应用，你觉得有用吗？\n女：非常有用！上面有详细的图片和视频，对新手特别好。"],"questions":[["她上周学了什么？",["切菜","做蛋糕","包饺子"],0],["她今晚打算做什么？",["水果沙拉","可乐鸡翅","红烧肉"],1],["她为什么不怎么做饭？",["没有厨房","不喜欢吃饭","不怎么会做，味道不好"],2],["奶奶说做泡菜要怎样？",["着急","用新鲜蔬菜，耐心地等","加很多糖"],1],["她觉得做菜应用对谁特别好？",["新手","厨师","老师"],0]]}];
